// Generated by `dokimos verification scaffold` from plan VP-B1-APPROVAL. Each body fails until
// it is written; `dokimos verification coverage` reports DOKIMOS-UNIMPLEMENTED as a placeholder.
namespace Approval.Tests

open Xunit
open Approval

module APR001Tests =
    let private allStates = [ Draft; Submitted; Approved; Rejected ]

    let private allCommands = [ Submit; Approve "approve-note"; Reject "reject-note"; Revise ]

    /// The command's case, ignoring any note payload.
    let private commandKind =
        function
        | Submit -> "Submit"
        | Approve _ -> "Approve"
        | Reject _ -> "Reject"
        | Revise -> "Revise"

    /// The legal (state, command kind) -> next state table from APR-001.
    let private table =
        Map.ofList
            [ (Draft, "Submit"), Submitted
              (Submitted, "Approve"), Approved
              (Submitted, "Reject"), Rejected
              (Rejected, "Revise"), Draft ]

    let private nextState state command = table |> Map.tryFind (state, commandKind command)

    /// A request in the given state, at a non-trivial version and with a recognisable note.
    let private requestIn state =
        { Domain.create "req-001" "Laptop purchase" with
            State = state
            Version = 7
            Note = "prior-note" }

    let private allPairs =
        [ for s in allStates do
              for c in allCommands -> s, c ]

    /// APR-001-O1: each of the four legal transitions reaches exactly the next state in the table, and increments the version by one.
    [<Fact>]
    let ``APR-001-O1`` () : unit =
        let fresh = Domain.create "req-new" "New request"
        Assert.Equal(Draft, fresh.State)
        Assert.Equal(0, fresh.Version)

        let legal =
            allPairs |> List.choose (fun (s, c) -> nextState s c |> Option.map (fun n -> s, c, n))

        Assert.Equal(4, legal.Length)

        legal
        |> List.iter (fun (from, command, expected) ->
            let before = requestIn from

            match Domain.decide command before with
            | Ok after ->
                Assert.Equal(expected, after.State)
                Assert.Equal(before.Version + 1, after.Version)
                Assert.Equal(before.Id, after.Id)
                Assert.Equal(before.Title, after.Title)
            | Error e -> failwithf "legal transition %A --%A--> %A was refused: %A" from command expected e)

        // A full lifecycle from a fresh request: every step increments the version by exactly one.
        let lifecycle =
            [ Submit, Submitted
              Reject "no", Rejected
              Revise, Draft
              Submit, Submitted
              Approve "yes", Approved ]

        let final =
            lifecycle
            |> List.fold
                (fun (req: Request) (command, expected) ->
                    match Domain.decide command req with
                    | Ok next ->
                        Assert.Equal(expected, next.State)
                        Assert.Equal(req.Version + 1, next.Version)
                        next
                    | Error e -> failwithf "lifecycle step %A from %A was refused: %A" command req.State e)
                fresh

        Assert.Equal(lifecycle.Length, final.Version)

    /// APR-001-O2: every other (state, command) pair fails closed with `InvalidTransition(state, command)`. The request, including its state, version and note, is unchanged.
    [<Fact>]
    let ``APR-001-O2`` () : unit =
        let illegal = allPairs |> List.filter (fun (s, c) -> nextState s c |> Option.isNone)

        // 4 states x 4 commands, minus the 4 legal pairs.
        Assert.Equal(12, illegal.Length)

        illegal
        |> List.iter (fun (state, command) ->
            let before = requestIn state
            let expectedUnchanged = requestIn state

            match Domain.decide command before with
            | Error(InvalidTransition(s, c)) ->
                Assert.Equal(state, s)
                Assert.Equal(command, c)
                Assert.Equal(expectedUnchanged, before)
                Assert.Equal(state, before.State)
                Assert.Equal(7, before.Version)
                Assert.Equal("prior-note", before.Note)
            | Ok after -> failwithf "illegal pair (%A, %A) was accepted and produced %A" state command after)
